using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpStdioServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a summarization prompt for the given text.")]
    public static IList<ChatMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum number of sentences.")] string? maxSentences = null)
    {
        var constraint = maxSentences is not null
            ? $" Use no more than {maxSentences} sentences."
            : string.Empty;

        return
        [
            new(ChatRole.User,
                $"Please provide a concise summary of the following text.{constraint}\n\n{text}")
        ];
    }
}

