#r "nuget: ModelContextProtocol, 1.4.0"
using System.Reflection;
var asm = typeof(ModelContextProtocol.Server.McpServerToolAttribute).Assembly;
var toolAttr = typeof(ModelContextProtocol.Server.McpServerToolAttribute);
Console.WriteLine("=== McpServerToolAttribute ===");
foreach (var c in toolAttr.GetConstructors()) Console.WriteLine($"  ctor: ({string.Join(", ", c.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name))})");
foreach (var p in toolAttr.GetProperties()) Console.WriteLine($"  prop: {p.PropertyType.Name} {p.Name}");

var promptAttr = typeof(ModelContextProtocol.Server.McpServerPromptAttribute);
Console.WriteLine("=== McpServerPromptAttribute ===");
foreach (var c in promptAttr.GetConstructors()) Console.WriteLine($"  ctor: ({string.Join(", ", c.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name))})");
foreach (var p in promptAttr.GetProperties()) Console.WriteLine($"  prop: {p.PropertyType.Name} {p.Name}");

// Find ChatMessage, ChatRole
foreach (var t in asm.GetExportedTypes().Where(t => t.Name.Contains("Chat") || t.Name.Contains("Message") || t.Name.Contains("Role")))
    Console.WriteLine($"Type: {t.FullName}");
EOF
dotnet script /tmp/check_api.csx 2>/dev/null

