using System.ComponentModel;
using ModelContextProtocol.Server;
using Microsoft.Extensions.Logging;

namespace McpStdioServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("fetch_post"), Description("Fetches a post by ID from the JSONPlaceholder API.")]
    public static async Task<string> FetchPostAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<ApiFetchTool> logger,
        [Description("The numeric post ID (1-100).")] int id)
    {
        logger.LogInformation("Fetching post {Id}", id);

        var client = httpClientFactory.CreateClient("api");
        var response = await client.GetAsync($"/posts/{id}");
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync();
    }
}

